sql.where:
gto.deleted = 0

    AND gto.operation_id = #{reqVO.operationId}


    AND gto.vehicle_id = #{reqVO.vehicleId}


    AND gto.garbage_type_id = #{reqVO.garbageTypeId}


    AND gto.garbage_weight = #{reqVO.garbageWeight}


    AND gto.plan_id = #{reqVO.planId}


    AND gto.equipment_status = #{reqVO.equipmentStatus}


    AND gto.progress = #{reqVO.progress}


    AND gto.destination = #{reqVO.destination}


    AND gto.abnormal_is_abnormal = #{reqVO.abnormalIsAbnormal}



    AND gto.entry_time BETWEEN #{reqVO.entryTime[0]} AND #{reqVO.entryTime[1]}



    AND gto.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
